import os
import subprocess
def get_os_version():
    '''Retrieve the OS version.'''
    try:
        with open("/etc/os-release") as f:
            for line in f:
                if line.startswith("PRETTY_NAME"):
                    return line.split("=")[1].strip().strip('"')
    except FileNotFoundError:
        return "Unknown OS Version"
def get_kernel_version():
