class CrosswordPuzzle:
    def __init__(self):
        # Grid representation (5x5 example)
        self.grid = [
            ['_', '_', '_', '_', '_'],
            ['_', '_', '_', '_', '_'],
            ['_', '_', '_', '_', '_'],
            ['_', '_', '_', '_', '_'],
            ['_', '_', '_', '_', '_']
        ]
        # Solutions for across and down clues
        self.solutions = {
            'across': {
                1: ('HELLO', (0, 0)),
                3: ('WORLD', (2, 0))
            },
            'down': {
                2: ('EARTH', (0, 2)),
                4: ('LOW', (0, 4))
            }
        }
        # Clues for across and down
        self.clues = {
            'across': {
                1: 'Greeting word',
                3: 'Our planet'
            },
            'down': {
                2: 'Third planet from the sun',
                4: 'Opposite of high'
            }
        }
    def display_grid(self):
        print("\nCurrent Crossword Grid:")
        for row in self.grid:
            print(' '.join(row))
        print()
    def display_clues(self):
        print("Across Clues:")
        for num, clue in self.clues['across'].items():
            print(f"{num}. {clue}")
        print("\nDown Clues:")
        for num, clue in self.clues['down'].items():
            print(f"{num}. {clue}")
        print()
    def enter_word(self, clue_number, direction, word):
        direction = direction.lower()
        if clue_number not in self.solutions[direction]:
            print("Invalid clue number or direction.")
            return False
        solution, (row, col) = self.solutions[direction][clue_number]
