            r, c = (row, col + i) if direction == 'across' else (row + i, col)
            if r < 0 or r >= len(self.grid) or c < 0 or c >= len(self.grid[0]):
                print(f"Word '{word}' exceeds grid boundaries at position ({r+1},{c+1}).")
